function kMatch(l){const q=F.q.toLowerCase();return(!q||(l.job+' '+l.colour+' '+l.count+' '+l.ctype+' '+l.prog+' '+l.buyer).toLowerCase().includes(q))&&(!F.a||l.slot===F.a)&&(!F.b||l.buyer===F.b)&&(!F.c||l.merch===F.c)&&(!F.d||l.ctype===F.d)&&(!F.e||l.fabType===F.e)&&(!F.f||l.fac===F.f)&&(!F.g||l.status===F.g)&&(!F.h||l.yd===F.h)&&(!F.quick||(F.quick==='late'?l.late:F.quick==='bal'?l.bal>0:F.quick==='dbal'?l.dbal>0:F.quick==='na'?l.fac==='Not assigned'&&l.bal>0:true))}
function kExec(m){const K=knitRows();const rows=K.filter(kMatch);const T=rows.reduce((a,l)=>({o:a.o+num(l.order),p:a.p+l.prod,b:a.b+l.bal,d:a.d+l.deliv,db:a.db+l.dbal,g:a.g+num(l.greige),ih:a.ih+(l.facType==='In-house'?num(l.order):0)}),{o:0,p:0,b:0,d:0,db:0,g:0,ih:0});
 const byF={};rows.forEach(l=>{const g=byF[l.fac]||(byF[l.fac]={k:l.fac,v:0});g.v+=num(l.order)});const byB={};rows.forEach(l=>{const g=byB[l.buyer]||(byB[l.buyer]={k:l.buyer,v:0});g.v+=num(l.order)});const byS={};rows.forEach(l=>{const g=byS[l.slot||'—']||(byS[l.slot||'—']={k:l.slot||'—',v:0});g.v+=l.prod});
 const p=pager(rows.length,80);
 m.innerHTML=bar()+cards([[t1(T.o),'Knitting qty'],[t1(T.p)+' · '+pct(T.p,T.o)+'%','Knitted','good'],[n(T.b)+' kg','Balance','warn','bal'],[t1(T.d),'Delivered to greige'],[n(T.db)+' kg','Delivery balance','warn','dbal'],[n(rows.filter(l=>l.late).length),'Late lines','bad','late']])+kFilters(K)+
 `<div class="vgrid"><div class="panel pad"><div class="ptitle">Knitting qty by factory</div>${hbars(Object.values(byF).sort((a,b)=>b.v-a.v).slice(0,10).map(x=>Object.assign(x,{t:t1(x.v)})))}<div class="muted" style="font-size:12.5px;margin-top:4px">In-house share ${pct(T.ih,T.o)}%</div></div><div class="panel pad"><div class="ptitle">Knitted by slot</div>${vbars(Object.values(byS).sort((a,b)=>String(a.k).localeCompare(String(b.k))).map(x=>Object.assign(x,{t:t1(x.v)})))}</div><div class="panel pad"><div class="ptitle">Knitting qty by buyer</div>${hbars(Object.values(byB).sort((a,b)=>b.v-a.v).slice(0,8).map(x=>Object.assign(x,{t:t1(x.v)})))}</div></div>
 <div class="panel" style="margin-top:12px"><div class="tablewrap"><table class="noband"><thead><tr class="hdr"><th class="sk sk0">Buyer · Job</th><th>Merchandiser</th><th>Count</th><th>Count type</th><th>Yarn brand</th><th>Yarn lot</th><th>Fabric</th><th class="num">GSM</th><th>Colour</th><th>M/C dia</th><th>F/dia</th><th>Factory</th><th>Program</th><th class="num">Order kg</th><th class="num">Knitted kg</th><th class="num">Balance kg</th><th class="num">Delivered kg</th><th class="num">Delivery bal. kg</th><th class="num">Greige stock</th><th>FOS rcvd</th><th>Knit start</th><th>Knit end</th><th>Completed</th><th>Ship date</th><th>Slot</th><th>Status</th><th>Remarks</th></tr></thead>
 <tbody>${rows.slice(p.from,p.to).map(l=>`<tr class="${l.key===SELLINE?'sel':''} ${l.late?'late':''}" data-ln="${esc(l.key)}"><td class="sk sk0"><b>${esc(l.buyer)}</b><div class="muted" style="font-size:12px">${esc(l.job)}</div></td><td>${esc(l.merch)}</td><td>${esc(l.count)}</td><td>${esc(l.ctype)}</td><td>${esc(l.brand)}</td><td>${esc(l.lot)}</td><td>${esc(l.des)}</td><td class="num">${esc(l.gsm)}</td><td>${esc(l.colour)}</td><td>${esc(l.dia)}</td><td>${esc(l.fdia)}</td><td>${esc(l.fac)}</td><td>${esc(l.prog)}</td><td class="num">${n(l.order)}</td><td class="num">${n(l.prod)}</td><td class="num">${n(l.bal)}</td><td class="num">${n(l.deliv)}</td><td class="num">${n(l.dbal)}</td><td class="num">${num(l.greige)?n(l.greige):'—'}</td><td>${fmt(l.fos)}</td><td>${fmt(l.pS)}</td><td>${fmt(l.pE)}</td><td>${fmt(l.done)}</td><td>${fmt(l.ship)}</td><td>${esc(l.slot)}</td><td>${pill(l.status==='Done'?'done':l.status==='Late'?'late':l.status==='Running'?'run':'none',l.status)}</td><td>${esc(l.remark)}</td></tr>`).join('')}</tbody>
 <tfoot><tr><td class="sk sk0"><b>${n(rows.length)} lines</b></td><td colspan="12"></td><td class="num"><b>${n(T.o)}</b></td><td class="num"><b>${n(T.p)}</b></td><td class="num"><b>${n(T.b)}</b></td><td class="num"><b>${n(T.d)}</b></td><td class="num"><b>${n(T.db)}</b></td><td class="num"><b>${n(T.g)}</b></td><td colspan="8"></td></tr></tfoot></table>${rows.length?'':'<div class="empty">No line</div>'}</div>${p.html}</div>`;
 bindCommon(m,()=>[['Buyer','Job','Merchandiser','Count','Count type','Brand','Lot','Fabric','GSM','Colour','M/C dia','F/dia','Factory','Program','Order kg','Knitted kg','Balance kg','Delivered kg','Delivery balance kg','Greige stock','FOS rcvd','Knit start','Knit end','Completed','Ship date','Slot','Status']].concat(rows.map(l=>[l.buyer,l.job,l.merch,l.count,l.ctype,l.brand,l.lot,l.des,l.gsm,l.colour,l.dia,l.fdia,l.fac,l.prog,l.order,l.prod,l.bal,l.deliv,l.dbal,l.greige,l.fos,l.pS,l.pE,l.done,l.ship,l.slot,l.status])))}
function kPlan(m){const ed=can('plan');const P=S.plans.slice().reverse();const cur=SELPLAN&&S.plans.find(p=>p.id===SELPLAN);
 const lossOf=f=>num(S.set.loss[f]!=null?S.set.loss[f]:S.set.loss.Other);
 m.innerHTML=bar()+cards([[n(S.plans.filter(p=>p.status==='Received').length),'Waiting knitting review','warn'],[n(S.plans.filter(p=>p.status==='Confirmed').length),'Confirmed'],[t1(S.plans.filter(p=>p.status==='Confirmed').reduce((a,p)=>a+p.lines.reduce((s,x)=>s+num(x.final),0),0)),'Confirmed knitting qty']])+
 (can('merch','plan')?`<div class="ms" style="margin-bottom:10px"><button class="btn primary" id="pNew">＋ Enter fabric order sheet</button></div>`:'')+
 (cur?planForm(cur,ed,lossOf):'')+
 `<div class="panel"><div class="tablewrap" style="min-height:0"><table class="noband"><thead><tr class="hdr"><th class="sk sk0">Job</th><th>Buyer</th><th>Merchandiser</th><th>Received</th><th class="num">Colours</th><th class="num">Finish kg</th><th class="num">Knitting kg</th><th>Status</th></tr></thead><tbody>${P.map(p=>`<tr data-pl="${p.id}" class="${p.id===SELPLAN?'sel':''}"><td class="sk sk0"><b>${esc(p.job)}</b></td><td>${esc(p.buyer)}</td><td>${esc(p.merch)}</td><td>${fmt(p.date)}</td><td class="num">${p.lines.length}</td><td class="num">${n(p.lines.reduce((a,x)=>a+num(x.finish),0))}</td><td class="num">${n(p.lines.reduce((a,x)=>a+num(x.final||x.req),0))}</td><td>${pill(p.status==='Confirmed'?'done':'wait',p.status==='Confirmed'?'Confirmed':'Waiting review')}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">No fabric order sheet received yet</td></tr>'}</tbody></table></div></div>
 <div class="panel pad" style="margin-top:12px"><div class="ptitle">Process loss by fabric type (knitting + dyeing)</div><div class="form" style="grid-template-columns:repeat(7,minmax(0,1fr))">${Object.entries(S.set.loss).map(([k,v])=>`<label>${esc(k)} %<input type="number" step="0.1" data-loss="${esc(k)}" value="${v}" ${ed?'':'disabled'}></label>`).join('')}</div><div class="muted" style="font-size:12.5px;margin-top:6px">Required knitting kg = finish fabric kg ÷ (1 − loss %). Replace with your matrix.</div></div>`;
 const nb=G('pNew');if(nb)nb.onclick=()=>{const id='P'+Date.now().toString(36);S.plans.push({id,job:'',buyer:'',merch:can('merch')?roleName():'',style:'',ship:'',slot:'',date:TODAY,status:'Received',lines:[{colour:'',count:'',ctype:'',fabric:'S/J',gsm:'',dia:'',finish:'',req:0,final:''}]});SELPLAN=id;save();render()};
 m.querySelectorAll('[data-pl]').forEach(r=>r.onclick=()=>{SELPLAN=r.dataset.pl;render();window.scrollTo(0,0)});
 m.querySelectorAll('[data-loss]').forEach(i=>i.onchange=()=>{S.set.loss[i.dataset.loss]=num(i.value);save();toast('Process loss saved');render()});
 if(cur)bindPlan(cur,ed,lossOf)}
function planForm(p,ed,lossOf){const locked=p.status==='Confirmed';const merchEd=can('merch','plan')&&!locked;
 return `<div class="panel pad" style="margin-bottom:12px"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap"><div class="ptitle" style="margin:0">Fabric order sheet → knitting plan</div><button class="btn sm" id="pClose">Close</button></div>
 <div class="form" style="grid-template-columns:repeat(6,minmax(0,1fr));margin-top:8px"><label>Job no.<input type="text" id="pJob" value="${esc(p.job)}" ${merchEd?'':'disabled'}></label><label>Buyer<input type="text" id="pBuyer" value="${esc(p.buyer)}" list="dlBuyer" ${merchEd?'':'disabled'}></label><label>Merchandiser<input type="text" id="pMerch" value="${esc(p.merch)}" ${merchEd?'':'disabled'}></label><label>Style<input type="text" id="pStyle" value="${esc(p.style)}" ${merchEd?'':'disabled'}></label><label>Ship date<input type="date" id="pShip" value="${esc(p.ship)}" ${merchEd?'':'disabled'}></label><label>Knitting slot<input type="text" id="pSlot" value="${esc(p.slot)}" placeholder="e.g. Oct'26 1st" ${merchEd?'':'disabled'}></label></div>
 <datalist id="dlBuyer">${uniq(KNIT,l=>l.buyer).map(b=>`<option value="${esc(b)}">`).join('')}</datalist><datalist id="dlCt">${SAF.map(s=>`<option value="${esc(s.count)}">`).join('')}</datalist>
 <div style="overflow-x:auto;margin-top:8px"><table class="colorrows"><thead><tr><th>Colour</th><th>Yarn count</th><th>Count type</th><th>Fabric</th><th>GSM</th><th>Dia</th><th class="num">Finish kg</th><th class="num">Loss %</th><th class="num">Required knitting kg</th><th class="num">Final knitting kg</th><th></th></tr></thead><tbody>${p.lines.map((x,i)=>{const req=Math.ceil(num(x.finish)/(1-lossOf(x.fabric)/100));return `<tr><td><input type="text" data-pf="colour|${i}" value="${esc(x.colour)}" ${merchEd?'':'disabled'}></td><td><input type="text" data-pf="count|${i}" value="${esc(x.count)}" placeholder="30/1" ${merchEd?'':'disabled'}></td><td><input type="text" list="dlCt" data-pf="ctype|${i}" value="${esc(x.ctype)}" ${merchEd?'':'disabled'}></td><td><select data-pf="fabric|${i}" ${merchEd?'':'disabled'}>${Object.keys(S.set.loss).map(k=>`<option ${k===x.fabric?'selected':''}>${k}</option>`).join('')}</select></td><td><input type="number" data-pf="gsm|${i}" value="${esc(x.gsm)}" style="width:70px" ${merchEd?'':'disabled'}></td><td><input type="text" data-pf="dia|${i}" value="${esc(x.dia)}" style="width:70px" ${merchEd?'':'disabled'}></td><td><input type="number" data-pf="finish|${i}" value="${esc(x.finish)}" style="width:90px" ${merchEd?'':'disabled'}></td><td class="num">${lossOf(x.fabric)}</td><td class="num"><b>${n(req)}</b></td><td><input type="number" data-pf="final|${i}" value="${esc(x.final||'')}" placeholder="${req}" style="width:90px" ${ed&&!locked?'':'disabled'}></td><td>${merchEd&&p.lines.length>1?`<button class="btn sm" data-pdel="${i}">✕</button>`:''}</td></tr>`}).join('')}</tbody></table></div>
 <div class="ms" style="margin-top:8px">${merchEd?'<button class="btn sm" id="pAdd">Add colour line</button><button class="btn" id="pSave">Save</button>':''}${ed&&!locked?'<button class="btn primary" id="pConfirm">Confirm colour-wise knitting qty</button>':''}${locked?`<span class="muted">Confirmed. Lines are in the execution summary as Not assigned.</span>`:''}</div></div>`}
function bindPlan(p,ed,lossOf){const rd=()=>{['Job','Buyer','Merch','Style','Ship','Slot'].forEach(k=>{const e=G('p'+k);if(e&&!e.disabled)p[k==='Merch'?'merch':k.toLowerCase()]=e.value.trim()});root.querySelectorAll('[data-pf]').forEach(i=>{if(i.disabled)return;const [f,ix]=i.dataset.pf.split('|');p.lines[+ix][f]=i.value})};
 G('pClose').onclick=()=>{SELPLAN=null;render()};
 root.querySelectorAll('[data-pf]').forEach(i=>i.onchange=()=>{rd();save();render()});
 const a=G('pAdd');if(a)a.onclick=()=>{rd();p.lines.push({colour:'',count:'',ctype:'',fabric:'S/J',gsm:'',dia:'',finish:'',final:''});save();render()};
 root.querySelectorAll('[data-pdel]').forEach(b=>b.onclick=()=>{rd();p.lines.splice(+b.dataset.pdel,1);save();render()});
 const s=G('pSave');if(s)s.onclick=()=>{rd();if(!p.job){toast('Enter the job no.');return}save();toast('Fabric order sheet saved. Waiting for knitting review.');render()};
 const c=G('pConfirm');if(c)c.onclick=()=>{rd();if(!p.job){toast('Enter the job no.');return}if(p.lines.some(x=>!x.colour||!(num(x.finish)>0))){toast('Every line needs a colour and finish kg');return}
  p.lines.forEach(x=>{x.req=Math.ceil(num(x.finish)/(1-lossOf(x.fabric)/100));if(!(num(x.final)>0))x.final=x.req});p.status='Confirmed';p.confirmedBy=roleName();p.confirmedAt=TODAY;save();toast(`${p.job}: ${p.lines.length} colour line(s) confirmed for knitting`);render()}}
function kAlloc(m){const K=knitRows().filter(l=>l.bal>0);const rows=K.filter(kMatch);const p=pager(rows.length,60);const edIn=can('plan'),edOut=can('ach');const parties=PARTIES();
 const inBal=K.filter(l=>l.facType==='In-house').reduce((a,l)=>a+l.bal,0),outBal=K.filter(l=>l.facType==='Outside').reduce((a,l)=>a+l.bal,0),naBal=K.filter(l=>l.fac==='Not assigned').reduce((a,l)=>a+l.bal,0);
 const byP={};K.filter(l=>l.facType==='Outside').forEach(l=>{byP[l.fac]=(byP[l.fac]||0)+l.bal});
 m.innerHTML=bar()+cards([[n(naBal)+' kg','Not assigned','bad','na'],[n(inBal)+' kg','In-house open'],[n(outBal)+' kg','Outside open','warn'],[(inBal/1000/Math.max(.1,S.set.cap)).toFixed(1)+' days','In-house load at '+S.set.cap+' t/day']])+
 `<div class="panel pad" style="margin-bottom:12px"><div class="form" style="grid-template-columns:repeat(3,minmax(0,1fr));align-items:end"><label>In-house capacity (t / day)<input type="number" step="0.1" id="sCap" value="${S.set.cap}" ${edIn?'':'disabled'}></label><label>Average requirement (t / day)<input type="number" step="0.1" id="sReq" value="${S.set.req}" ${edIn?'':'disabled'}></label><div>Outside needed about <b>${Math.max(0,S.set.req-S.set.cap).toFixed(1)} t / day</b></div></div>${Object.keys(byP).length?`<div class="ptitle" style="margin-top:10px">Open balance by outside party</div>${hbars(Object.entries(byP).map(([k,v])=>({k,v,t:n(v)+' kg'})).sort((a,b)=>b.v-a.v))}`:''}</div>`+kFilters(K)+
 `<div class="panel"><div class="tablewrap"><table class="noband"><thead><tr class="hdr"><th class="sk sk0">Buyer · Job</th><th>Count type</th><th>Fabric</th><th class="num">GSM</th><th>Colour</th><th>Dia</th><th class="num">Balance kg</th><th>Factory</th><th>Program no.</th><th>Plan start</th><th>Plan end</th></tr></thead><tbody>${rows.slice(p.from,p.to).map(l=>{const can2=(edIn&&(l.facType!=='Outside'))||(edOut&&l.facType!=='In-house')||edIn;return `<tr class="${l.late?'late':''}"><td class="sk sk0"><b>${esc(l.buyer)}</b><div class="muted" style="font-size:12px">${esc(l.job)}</div></td><td>${esc(l.ctype)}</td><td>${esc(l.des)}</td><td class="num">${esc(l.gsm)}</td><td>${esc(l.colour)}</td><td>${esc(l.dia)}</td><td class="num">${n(l.bal)}</td><td>${(edIn||edOut)?`<select class="inl" data-fa="${esc(l.key)}">${['Not assigned','NFL (in-house)','Greige stock'].concat(parties).filter(f=>edIn||(f!=='NFL (in-house)')).map(f=>`<option ${f===l.fac?'selected':''}>${esc(f)}</option>`).join('')}</select>`:esc(l.fac)}</td><td>${(edIn||edOut)?`<input type="text" style="width:90px" data-pa="prog|${esc(l.key)}" value="${esc(l.prog)}">`:esc(l.prog)}</td><td>${edIn?`<input type="date" data-pa="start|${esc(l.key)}" value="${esc(l.pS)}">`:fmt(l.pS)}</td><td>${edIn?`<input type="date" data-pa="end|${esc(l.key)}" value="${esc(l.pE)}">`:fmt(l.pE)}</td></tr>`}).join('')}</tbody></table>${rows.length?'':'<div class="empty">No open line</div>'}</div>${p.html}</div>`;
 bindCommon(m);const sc=G('sCap');sc.onchange=()=>{S.set.cap=num(sc.value);save();render()};const sr=G('sReq');sr.onchange=()=>{S.set.req=num(sr.value);save();render()};
 m.querySelectorAll('[data-fa]').forEach(s=>s.onchange=()=>{const k=s.dataset.fa;S.alloc[k]=Object.assign({},S.alloc[k],{fac:s.value,by:roleName(),at:TODAY});save();toast('Factory saved: '+s.value);render()});
 m.querySelectorAll('[data-pa]').forEach(i=>i.onchange=()=>{const [f,...k]=i.dataset.pa.split('|');const key=k.join('|');S.alloc[key]=Object.assign({},S.alloc[key],{[f]:i.value});save();toast('Saved')})}
function kDaily(m){const K=knitRows();const open=K.filter(l=>l.bal>0||l.dbal>0);const ed=can('rep');const cur=SELLINE&&K.find(l=>l.key===SELLINE);const D=S.daily.slice().reverse();
 const today=S.daily.filter(d=>d.date===TODAY);
 m.innerHTML=bar()+cards([[n(today.reduce((a,d)=>a+num(d.prod),0))+' kg','Knitted today'],[n(today.reduce((a,d)=>a+num(d.deliv),0))+' kg','Delivered today'],[n(S.daily.reduce((a,d)=>a+num(d.rej),0))+' kg','Rejected (all entries)','warn'],[n(S.daily.length),'Entries']])+
 (ed?`<div class="panel pad"><div class="ptitle">Daily production entry</div><datalist id="dlLine">${open.slice(0,1500).map(l=>`<option value="${esc(l.key)}">${esc(l.buyer)} ${esc(l.job)} · ${esc(l.colour)} · ${esc(l.ctype)} · bal ${n(l.bal)}</option>`).join('')}</datalist>
  <div class="form" style="grid-template-columns:repeat(4,minmax(0,1fr))"><label class="span2">Knitting line (job · colour · count)<input type="text" id="dLine" list="dlLine" value="${esc(cur?cur.key:'')}" placeholder="Search job or colour"></label><label>Date<input type="date" id="dDate" value="${TODAY}"></label><label>Shift<select id="dShift"><option>A</option><option>B</option><option>C</option><option>Day</option><option>Night</option></select></label>
  <label>Knitted kg<input type="number" id="dProd" min="0" step="any"></label><label>Delivered to greige store kg<input type="number" id="dDel" min="0" step="any"></label><label>Rejected kg<input type="number" id="dRej" min="0" step="any"></label><label>Machine / remarks<input type="text" id="dRem"></label></div>
  <div class="ms" style="margin-top:8px"><button class="btn primary" id="dSave">Post</button><span class="muted" id="dInfo" style="align-self:center;font-size:12.5px"></span></div></div>`:'')+
 `<div class="panel" style="margin-top:12px"><div class="tablewrap" style="min-height:0"><table class="noband"><thead><tr class="hdr"><th>Date</th><th>Shift</th><th>Buyer · Job</th><th>Colour</th><th>Count type</th><th>Factory</th><th class="num">Knitted kg</th><th class="num">Delivered kg</th><th class="num">Rejected kg</th><th>Remarks</th><th>By</th></tr></thead><tbody>${D.map(d=>{const l=K.find(x=>x.key===d.key)||{};return `<tr><td>${fmt(d.date)}</td><td>${esc(d.shift)}</td><td>${esc(l.buyer||'')} ${esc(l.job||'')}</td><td>${esc(l.colour||'')}</td><td>${esc(l.ctype||'')}</td><td>${esc(l.fac||'')}</td><td class="num">${n(d.prod)}</td><td class="num">${n(d.deliv)}</td><td class="num">${n(d.rej)}</td><td>${esc(d.rem)}</td><td>${esc(d.by)}</td></tr>`}).join('')||'<tr><td colspan="11" class="muted">No entry yet</td></tr>'}</tbody></table></div></div>`;
 const li=G('dLine');const info=()=>{const l=K.find(x=>x.key===li.value);G('dInfo').textContent=l?`Order ${n(l.order)} · knitted ${n(l.prod)} · balance ${n(l.bal)} · undelivered ${n(l.dbal)} kg`:''};if(li){li.oninput=info;info()}
 const sv=G('dSave');if(sv)sv.onclick=()=>{const l=K.find(x=>x.key===li.value);const pr=num(G('dProd').value),dv=num(G('dDel').value),rj=num(G('dRej').value);
  if(!l){toast('Choose a knitting line');return}if(!(pr>0||dv>0)){toast('Enter knitted or delivered kg');return}if(dv>l.prod+pr-l.deliv+1e-9){toast(`Only ${n(l.prod+pr-l.deliv)} kg is knitted and not yet delivered`);return}
  if(pr>l.bal*1.1+1){toast(`Knitted kg is more than 10% over the balance (${n(l.bal)} kg). Check the entry.`);return}
  S.daily.push({key:l.key,date:G('dDate').value||TODAY,shift:G('dShift').value,prod:pr,deliv:dv,rej:rj,rem:G('dRem').value.trim(),by:roleName()});SELLINE=l.key;save();toast('Production posted. Summary updated.');render()}}
function kMeet(m){const K=knitRows();const late=K.filter(l=>l.late),soon=K.filter(l=>!l.late&&l.bal>0&&l.pE&&l.pE>=TODAY&&days(TODAY,l.pE)<=7),na=K.filter(l=>l.fac==='Not assigned'&&l.bal>0),und=K.filter(l=>l.dbal>0);
 const issued={};S.iss.forEach(i=>{issued[i.job]=(issued[i.job]||0)+num(i.kg)});YDEL.forEach(j=>{issued[j.job]=(issued[j.job]||0)+j.progs.reduce((a,p)=>a+p.kg,0)});const noYarn=K.filter(l=>l.bal>0&&!issued[l.job]);
 const tbl=(list,cols)=>`<div style="overflow-x:auto"><table class="btab"><thead><tr><th>Buyer · Job</th><th>Colour</th><th>Count type</th><th>Factory</th>${cols.map(c=>`<th class="num">${c[0]}</th>`).join('')}</tr></thead><tbody>${list.slice(0,60).map(l=>`<tr><td><b>${esc(l.buyer)}</b> ${esc(l.job)}</td><td>${esc(l.colour)}</td><td>${esc(l.ctype)}</td><td>${esc(l.fac)}</td>${cols.map(c=>`<td class="num">${c[1](l)}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="9" class="muted">None</td></tr>'}</tbody></table></div>${list.length>60?`<div class="muted" style="font-size:12.5px">Showing 60 of ${list.length}</div>`:''}`;
 m.innerHTML=bar()+cards([[n(late.length),'Late lines','bad'],[n(soon.length),'Due in 7 days','warn'],[n(na.length),'Not assigned','bad'],[n(noYarn.length),'Yarn not issued','warn'],[n(und.reduce((a,l)=>a+l.dbal,0))+' kg','Knitted, not delivered']])+
 `<div class="ms" style="margin-bottom:10px"><button class="btn primary" id="mPrint">Print meeting sheet</button></div>
 <div class="panel pad"><div class="ptitle">Late (${late.length})</div>${tbl(late,[['Balance kg',l=>n(l.bal)],['Plan end',l=>fmt(l.pE)]])}</div>
 <div class="panel pad" style="margin-top:12px"><div class="ptitle">Due in 7 days (${soon.length})</div>${tbl(soon,[['Balance kg',l=>n(l.bal)],['Plan end',l=>fmt(l.pE)]])}</div>
 <div class="panel pad" style="margin-top:12px"><div class="ptitle">Not assigned to a factory (${na.length})</div>${tbl(na,[['Balance kg',l=>n(l.bal)]])}</div>
 <div class="panel pad" style="margin-top:12px"><div class="ptitle">Yarn not issued (${noYarn.length})</div>${tbl(noYarn,[['Balance kg',l=>n(l.bal)]])}</div>
 <div class="panel pad" style="margin-top:12px"><div class="ptitle">Knitted, not delivered to greige store (${und.length})</div>${tbl(und,[['Undelivered kg',l=>n(l.dbal)]])}</div>`;
 G('mPrint').onclick=()=>{const sec=(t,list,cols)=>`<h4>${t} (${list.length})</h4><table><tr><th>Buyer · Job</th><th>Colour</th><th>Count type</th><th>Factory</th>${cols.map(c=>`<th>${c[0]}</th>`).join('')}</tr>${list.slice(0,200).map(l=>`<tr><td>${esc(l.buyer)} ${esc(l.job)}</td><td>${esc(l.colour)}</td><td>${esc(l.ctype)}</td><td>${esc(l.fac)}</td>${cols.map(c=>`<td>${c[1](l)}</td>`).join('')}</tr>`).join('')}</table>`;
  printDoc('Knitting Production Meeting',sec('Late',late,[['Balance kg',l=>n(l.bal)],['Plan end',l=>fmt(l.pE)]])+sec('Due in 7 days',soon,[['Balance kg',l=>n(l.bal)]])+sec('Not assigned',na,[['Balance kg',l=>n(l.bal)]])+sec('Yarn not issued',noYarn,[['Balance kg',l=>n(l.bal)]])+sec('Knitted, not delivered',und,[['Undelivered kg',l=>n(l.dbal)]])+'<div class="sig"><div>Knitting Planner</div><div>Knitting Manager</div><div>Management</div></div>')}}
