const KV_LIST=[['exec','Production & execution summary'],['plan','New plan (fabric order sheet)'],['alloc','Planning & allocation'],['daily','Daily production'],['meet','Production meeting']];
function render(){const ae=document.activeElement;const keep=ae&&ae.tagName==='INPUT'&&ae.type==='search'&&ae.id&&root.contains(ae)?ae:null;const m=G('ykmain');
 if(TOP==='yarn')({dash:yDash,min:yMin,stock:yStock,rcv:yRcv,iss:yIss,dead:yDead,urgent:yUrgent,req:yReq})[YV](m);else({exec:kExec,plan:kPlan,alloc:kAlloc,daily:kDaily,meet:kMeet})[KV](m);
 if(keep){const nw=root.querySelector('#'+keep.id);if(nw&&nw!==keep){const hi=nw.oninput;keep.oninput=e=>{nw.value=keep.value;if(hi)hi.call(nw,e)};nw.replaceWith(keep);try{keep.focus({preventScroll:true})}catch(e){}}}}
