return{main:[['yarn','Yarn Store'],['knit','Knitting']],get top(){return TOP},get views(){return TOP==='yarn'?YV_LIST:KV_LIST},get view(){return TOP==='yarn'?YV:KV},
 setTop(t){TOP=t;resetF();SELLINE=null;SELPLAN=null;render()},setView(v){if(TOP==='yarn')YV=v;else KV=v;resetF();render()},reset(){S=JSON.parse(JSON.stringify(DEF));save();render()},rerender:render,roleSel:rs};
